// src/core/cameraManager.js
export class CameraManager {
  constructor() {
    this.videoEl = null;
    this.stream = null;
    this.currentFacing = "user"; // 'user' | 'environment'
    this.currentDeviceId = null;
  }

  setVideoElement(videoEl) {
    this.videoEl = videoEl;
  }

  getCurrentFacingMode() {
    return this.currentFacing;
  }

  async hasMultipleCameras() {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      return devices.filter((d) => d.kind === "videoinput").length > 1;
    } catch {
      return false;
    }
  }

  async _enumerateVideoInputs() {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      return devices.filter((d) => d.kind === "videoinput");
    } catch (e) {
      console.warn("[camera] enumerateDevices failed:", e);
      return [];
    }
  }

  _pickByFacing(devices, preferredFacing) {
    const labelHas = (label, keyword) =>
      (label || "").toLowerCase().includes(keyword);
    const isBack = (d) =>
      /back|rear|environment/.test((d.label || "").toLowerCase());
    const isFront = (d) =>
      /front|user|face/.test((d.label || "").toLowerCase());

    if (preferredFacing === "environment") {
      return devices.find(isBack) || null;
    }
    return devices.find(isFront) || null;
  }

  async _chooseDeviceId(preferredFacing = "user") {
    const videos = await this._enumerateVideoInputs();
    if (!videos.length) return null;

    // 先用已知 deviceId
    if (
      this.currentDeviceId &&
      videos.some((v) => v.deviceId === this.currentDeviceId)
    ) {
      return this.currentDeviceId;
    }
    // 嘗試依 label 判斷前/後鏡頭
    const match = this._pickByFacing(videos, preferredFacing);
    if (match) return match.deviceId;

    // 找不到就回傳第一個
    return videos[0].deviceId || null;
  }

  _attempts(preferredFacing, deviceId) {
    // 逐級退讓（不要使用 exact 解析度與 aspectRatio）
    return [
      {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          facingMode: preferredFacing, // 非 exact，交給 UA 決定
          width: { ideal: 1920 },
          height: { ideal: 1080 },
          frameRate: { ideal: 30, max: 30 },
        },
        audio: false,
      },
      {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          facingMode: preferredFacing,
          width: { ideal: 1280 },
          height: { ideal: 720 },
          frameRate: { ideal: 30, max: 30 },
        },
        audio: false,
      },
      {
        video: {
          facingMode: preferredFacing,
        },
        audio: false,
      },
      {
        video: true,
        audio: false,
      },
    ];
  }

  _attachStream(stream) {
    this.stream = stream;
    if (this.videoEl) {
      try {
        this.videoEl.srcObject = stream;
        this.videoEl.playsInline = true;
        this.videoEl.muted = true; // iOS 自動播放需要 muted
        this.videoEl.autoplay = true;
        const p = this.videoEl.play();
        if (p && typeof p.catch === "function") {
          p.catch(() => {});
        }
      } catch (e) {
        console.warn("[camera] attach video srcObject failed:", e);
      }
    }
  }

  _stopStream() {
    if (this.stream) {
      try {
        this.stream.getTracks().forEach((t) => t.stop());
      } catch {}
      this.stream = null;
    }
    if (this.videoEl) {
      try {
        this.videoEl.srcObject = null;
      } catch {}
    }
  }

  async startCamera(preferredFacing) {
    // 若外層沒傳，就用目前記錄的
    const facing = preferredFacing || this.currentFacing;

    // 確保舊流釋放
    this._stopStream();

    // 選裝置
    if (!this.currentDeviceId) {
      this.currentDeviceId = await this._chooseDeviceId(facing);
    }

    const attempts = this._attempts(facing, this.currentDeviceId);
    let lastErr = null;

    for (let i = 0; i < attempts.length; i++) {
      const c = attempts[i];
      try {
        console.log("[camera] try constraints", JSON.stringify(c));
        const stream = await navigator.mediaDevices.getUserMedia(c);

        const [track] = stream.getVideoTracks();
        const settings = track.getSettings ? track.getSettings() : {};
        // 更新實際成功的 deviceId 與 facing
        this.currentDeviceId = settings.deviceId || this.currentDeviceId;
        // 有些 UA 不回 facingMode，保留原值
        if (settings.facingMode) this.currentFacing = settings.facingMode;

        console.log("[camera] SUCCESS with settings:", settings);
        this._attachStream(stream);
        return;
      } catch (err) {
        lastErr = err;
        if (err.name === "OverconstrainedError") {
          console.warn(
            `[camera] Overconstrained on: ${
              err.constraint || "unknown"
            } → fallback`
          );
          // 若是 deviceId 精確匹配造成，移除 deviceId 再重試同層一次
          if (c.video && c.video.deviceId) {
            try {
              const c2 = JSON.parse(JSON.stringify(c));
              delete c2.video.deviceId;
              console.log("[camera] retry same tier without deviceId");
              const stream2 = await navigator.mediaDevices.getUserMedia(c2);
              const [track2] = stream2.getVideoTracks();
              const settings2 = track2.getSettings ? track2.getSettings() : {};
              this.currentDeviceId = settings2.deviceId || this.currentDeviceId;
              if (settings2.facingMode)
                this.currentFacing = settings2.facingMode;
              console.log(
                "[camera] SUCCESS after removing deviceId:",
                settings2
              );
              this._attachStream(stream2);
              return;
            } catch (err2) {
              console.warn(
                "[camera] retry without deviceId failed:",
                err2.name,
                err2.message
              );
            }
          }
        } else {
          console.warn("[camera] getUserMedia failed:", err.name, err.message);
        }
        // 進入下一層嘗試
      }
    }

    // 全部失敗
    throw lastErr || new Error("Camera start failed");
  }

  stopCamera() {
    this._stopStream();
  }

  async switchCamera() {
    // 切換鏡頭偏好（若目前 user → environment，反之亦然）
    this.currentFacing = this.currentFacing === "user" ? "environment" : "user";
    // 切換後不保留舊 deviceId，讓挑選邏輯重新判斷
    this.currentDeviceId = null;
    await this.startCamera(this.currentFacing);
  }
}
