export function initCore(els, callbacks = {}) {
  videoEl = els.videoEl;
  bgCanvas = els.bgCanvas;
  maskCanvas = els.maskCanvas;
  outCanvas = els.outCanvas;
  bgVideoEl = els.bgVideoEl || null;
  bgMoonVideoEl = els.bgMoonVideoEl || null;
  iosMoonVideoEl = els.iosMoonVideoEl || null;
  isIOSDevice = els.isIOSDevice || false;
  contentFrameEl = els.contentFrameEl || null; // ← 新增：由外部傳入
  isDesktopDevice =
    typeof els.isDesktopDevice === "boolean"
      ? els.isDesktopDevice
      : detectDesktop(); // ← 新增：桌機判斷（可被覆蓋）

  console.log("📱 SegmentationCore 設備資訊:", {
    isIOSDevice,
    isDesktopDevice,
    hasIOSMoonVideo: !!iosMoonVideoEl,
    hasNormalMoonVideo: !!bgMoonVideoEl,
  });

  bgCtx = bgCanvas.getContext("2d");
  maskCtx = maskCanvas.getContext("2d");
  outCtx = outCanvas.getContext("2d");

  if (typeof callbacks.onStatus === "function") onStatus = callbacks.onStatus;
  if (typeof callbacks.onStats === "function") onStats = callbacks.onStats;

  // 初始化管理器
  cameraManager.setVideoElement(videoEl);
  backgroundRenderer.setIOSDevice(isIOSDevice);
  recordingManager.setProgressCallback(callbacks.onProgress);

  // ✅ 啟動就同步一次 Canvas 尺寸（包含 DPR 對齊）
  syncCanvasSize();

  // ✅ 視窗大小變更時同步（避免旋轉或視窗改變導致糊掉）
  window.addEventListener("resize", onResize);
}

