// -----------------------------------------------------------------------------
// 畫布尺寸同步
// -----------------------------------------------------------------------------
export function syncCanvasSize() {
  const stageEl = outCanvas.closest(".stage") || outCanvas.parentElement;

  // 1) 取可視區尺寸（行動裝置地址列收合更準）
  const getViewportSize = () => {
    const vv = window.visualViewport;
    return {
      w: Math.round(
        vv?.width ||
          window.innerWidth ||
          document.documentElement.clientWidth ||
          360
      ),
      h: Math.round(
        vv?.height ||
          window.innerHeight ||
          document.documentElement.clientHeight ||
          640
      ),
    };
  };

  // 2) CSS 尺寸（邏輯像素）：滿版就直接吃 viewport；否則吃容器 rect
  let cssW, cssH;
  if (CONFIG.DISPLAY?.FULLBLEED) {
    const { w, h } = getViewportSize();
    cssW = w;
    cssH = h;

    if (stageEl && stageEl.style) {
      stageEl.style.position = "fixed";
      stageEl.style.top = "0";
      stageEl.style.left = "0";
      stageEl.style.right = "0";
      stageEl.style.bottom = "0";
      stageEl.style.width = "100dvw";
      stageEl.style.height = "100dvh";
      stageEl.style.margin = "0";
      stageEl.style.padding = "0";
      stageEl.style.overflow = "hidden";
    }
  } else {
    const rect = stageEl.getBoundingClientRect();
    cssW = Math.max(320, Math.round(rect.width));
    cssH = Math.max(240, Math.round(rect.height));
  }

  // 記住 CSS 尺寸（給 pillarbox 換算用）
  lastCssW = cssW;
  lastCssH = cssH;

  // 3) 像素層級的軟上限：限制「有效 DPR」而非 CSS 尺寸
  const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 3));
  const maxWpx = window.innerWidth > 768 ? 1920 : 1280;
  const maxHpx = window.innerHeight > 1024 ? 1080 : 1280;

  const dprEff = Math.min(dpr, maxWpx / cssW, maxHpx / cssH);

  const pixelW = Math.round(cssW * dprEff);
  const pixelH = Math.round(cssH * dprEff);

  const setSize = (c) => {
    if (c.width !== pixelW || c.height !== pixelH) {
      c.width = pixelW; // 實際像素（決定清晰度）
      c.height = pixelH;
    }
    c.style.width = `${cssW}px`; // CSS 尺寸（決定畫面是否滿版）
    c.style.height = `${cssH}px`;
  };

  [bgCanvas, maskCanvas, outCanvas, videoDrawCanvas, compositeCanvas].forEach(
    setSize
  );

  lastMaskSize = { w: outCanvas.width, h: outCanvas.height };
}

// -----------------------------------------------------------------------------
// 背景繪製（含「影片」背景選項）
// -----------------------------------------------------------------------------
function renderBackgroundTo(ctx, w, h) {
  const bgType =
    (CONFIG.BACKGROUND && CONFIG.BACKGROUND.TYPE) ||
    (CONFIG.BACKGROUND_EFFECTS &&
      CONFIG.BACKGROUND_EFFECTS.DEFAULT_BACKGROUND) ||
    "original";
  const intensity =
    CONFIG.BACKGROUND && typeof CONFIG.BACKGROUND.INTENSITY === "number"
      ? CONFIG.BACKGROUND.INTENSITY
      : (CONFIG.BACKGROUND_EFFECTS &&
          CONFIG.BACKGROUND_EFFECTS.EFFECT_INTENSITY) ??
        0.5;

  ctx.clearRect(0, 0, w, h);
  animT += 0.016;

  if (bgType === "original") {
    // 透明
    return;
  }
  if (bgType === "waves") {
    const grad = ctx.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, "#1a2332");
    grad.addColorStop(0.5, "#2d3a50");
    grad.addColorStop(1, "#0f1419");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = `rgba(100,200,255,${intensity * 0.6})`;
    ctx.lineWidth = 2;
    for (let i = 0; i < 8; i++) {
      ctx.beginPath();
      for (let x = 0; x < w; x += 5) {
        const off = i * 50;
        const y =
          h / 2 + Math.sin((x + off) * 0.012 + animT * 1.2) * 20 * intensity;
        if (x === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    return;
  }
  if (bgType === "frequency") {
    ctx.fillStyle = "#0a0a0a";
    ctx.fillRect(0, 0, w, h);
    const bands = 48;
    const bw = w / bands;
    for (let i = 0; i < bands; i++) {
      const x = i * bw;
      const bh =
        (Math.sin(animT * 2 + i * 0.2) * 0.5 + 0.5) * h * 0.5 * intensity;
      const hue = (animT * 30 + i * 10) % 360;
      ctx.fillStyle = `hsla(${hue},70%,60%,0.8)`;
      ctx.fillRect(x, h - bh, bw - 1, bh);
    }
    return;
  }
  if (bgType === "video" && bgVideoEl) {
    // 以 cover 方式鋪滿
    const vw = bgVideoEl.videoWidth || 1;
    const vh = bgVideoEl.videoHeight || 1;
    if (bgVideoEl.readyState >= 2) {
      const scale = Math.max(w / vw, h / vh);
      const dw = Math.round(vw * scale);
      const dh = Math.round(vh * scale);
      const ox = Math.round((w - dw) / 2);
      const oy = Math.round((h - dh) / 2);
      try {
        if (bgVideoEl.paused) bgVideoEl.play().catch(() => {});
      } catch {}
      ctx.globalAlpha = Math.min(1, 0.3 + intensity * 0.7);
      ctx.drawImage(bgVideoEl, 0, 0, vw, vh, ox, oy, dw, dh);
      ctx.globalAlpha = 1;
    }
    return;
  }

  // 月相影片背景（略：維持你原本流程）
  if (bgType === "moon_video" && bgMoonVideoEl) {
    try {
      if (bgMoonVideoEl.readyState >= 2 && !bgMoonVideoEl.paused) {
        const vw = bgMoonVideoEl.videoWidth || bgMoonVideoEl.width || 1;
        const vh = bgMoonVideoEl.videoHeight || bgMoonVideoEl.height || 1;
        if (vw > 1 && vh > 1) {
          const scale = Math.max(w / vw, h / vh);
          const dw = Math.round(vw * scale);
          const dh = Math.round(vh * scale);
          const ox = Math.round((w - dw) / 2);
          const oy = Math.round((h - dh) / 2);
          ctx.globalAlpha = Math.min(1, 0.3 + intensity * 0.7);
          ctx.drawImage(bgMoonVideoEl, 0, 0, vw, vh, ox, oy, dw, dh);
          ctx.globalAlpha = 1;
        }
      } else if (bgMoonVideoEl && bgMoonVideoEl.paused) {
        bgMoonVideoEl.play().catch((e) => console.warn("月相影片播放失敗:", e));
      }
    } catch (e) {
      console.warn("月相影片渲染錯誤:", e);
    }
    return;
  }

  // custom_moon_bg 分支（略）：維持你原本流程
}

// 包一層統一呼叫（你原本的）
function renderBackground(w, h) {
  backgroundRenderer.setIOSDevice(isIOSDevice);
  backgroundRenderer.setVideoElement(videoEl);
  backgroundRenderer.renderBackgroundTo(
    bgCtx,
    w,
    h,
    bgVideoEl,
    bgMoonVideoEl,
    iosMoonVideoEl
  );
}

// -----------------------------------------------------------------------------
// 蒙版處理（EMA 平滑 + 邊緣羽化）
// -----------------------------------------------------------------------------
function emaUpdate(srcF32, w, h) {
  const N = w * h;
  if (!lastMaskF32 || lastMaskSize.w !== w || lastMaskSize.h !== h) {
    lastMaskF32 = new Float32Array(N);
    lastMaskF32.set(srcF32);
    lastMaskSize = { w, h };
    return lastMaskF32;
  }
  const a = CONFIG.SMOOTHING.TEMPORAL_ALPHA;
  for (let i = 0; i < N; i++) {
    lastMaskF32[i] = a * lastMaskF32[i] + (1 - a) * srcF32[i];
  }
  return lastMaskF32;
}

function buildAlphaImage(maskF32, w, h) {
  const T = CONFIG.SMOOTHING.THRESHOLD;
  const N = w * h;
  const img = new ImageData(w, h);
  for (let i = 0, j = 0; i < N; i++, j += 4) {
    const v = maskF32[i];
    const a = v >= T ? Math.min(255, Math.round(v * 255)) : 0;
    img.data[j] = 0;
    img.data[j + 1] = 0;
    img.data[j + 2] = 0;
    img.data[j + 3] = a;
  }
  maskBaseCanvas.width = w;
  maskBaseCanvas.height = h;
  maskBaseCtx.putImageData(img, 0, 0);

  const VW = outCanvas.width,
    VH = outCanvas.height;
  maskUpscaleCanvas.width = VW;
  maskUpscaleCanvas.height = VH;
  maskUpscaleCtx.clearRect(0, 0, VW, VH);
  maskUpscaleCtx.imageSmoothingEnabled = true;
  maskUpscaleCtx.imageSmoothingQuality = "high";
  maskUpscaleCtx.drawImage(maskBaseCanvas, 0, 0, VW, VH);

  const blurPx = CONFIG.SMOOTHING.EDGE_FEATHER_PX;
  maskSoftCanvas.width = VW;
  maskSoftCanvas.height = VH;
  maskSoftCtx.clearRect(0, 0, VW, VH);
  maskSoftCtx.filter = blurPx > 0 ? `blur(${blurPx}px)` : "none";
  maskSoftCtx.drawImage(maskUpscaleCanvas, 0, 0);
  maskSoftCtx.filter = "none";
  return maskSoftCanvas;
}

// -----------------------------------------------------------------------------
// 臉部檢測 / 區域與疊圖
// -----------------------------------------------------------------------------
function checkFacesInArea(detections) {
  return detections; // 目前整畫面
}

function renderOverlay(detections) {
  const W = outCanvas.width,
    H = outCanvas.height;
  outCtx.save();
  outCtx.translate(W, 0);
  outCtx.scale(-1, 1);

  const facesIn = checkFacesInArea(detections);
  outCtx.restore();

  if (detections.length > 0) {
    console.log(
      "🔍 偵測到",
      detections.length,
      "個人臉，符合條件的:",
      facesIn.length
    );
  }

  const currentFaceDetectionState =
    facesIn.length >= CONFIG.FACE_DETECTION_SETTINGS.REQUIRED_FACES;
  if (currentFaceDetectionState !== lastFaceDetectionState) {
    if (currentFaceDetectionState) onStatus?.("TRIGGER_TEST_EFFECT");
    else onStatus?.("STOP_TEST_EFFECT");
    lastFaceDetectionState = currentFaceDetectionState;
  }

  onStats({
    faceCount: detections.length,
    facesInArea: facesIn.length,
    moonActive: facesIn.length >= CONFIG.FACE_DETECTION_SETTINGS.REQUIRED_FACES,
  });
}

// -----------------------------------------------------------------------------
// 主渲染迴圈
// -----------------------------------------------------------------------------
async function renderLoop() {
  if (!running) return;
  const now = performance.now();
  const W = outCanvas.width,
    H = outCanvas.height;

  // 1) 先把相機畫面投到 videoDrawCanvas（cover + 置中）
  videoDrawCtx.clearRect(0, 0, W, H);
  const vw = videoEl.videoWidth || 1,
    vh = videoEl.videoHeight || 1;
  const scale = Math.max(W / vw, H / vh);
  const dw = Math.round(vw * scale),
    dh = Math.round(vh * scale);
  const ox = Math.round((W - dw) / 2),
    oy = Math.round((H - dh) / 2);
  try {
    videoDrawCtx.drawImage(videoEl, 0, 0, vw, vh, ox, oy, dw, dh);
  } catch {}

  // 2) 接著決定「底層」要畫什麼
  bgCtx.clearRect(0, 0, W, H);
  if (CONFIG.BACKGROUND?.TYPE === "person_overlay") {
    // 底層以相機畫面為主，根据镜头模式决定是否镜像
    bgCtx.save();
    if (currentFacingMode === "user") {
      // 前镜头：背景层镜像（因为outputCanvas会被CSS镜像，需要预镜像以抵消）
      bgCtx.translate(W, 0);
      bgCtx.scale(-1, 1);
    }
    // 后镜头：不镜像背景层
    bgCtx.drawImage(videoDrawCanvas, 0, 0, W, H);
    bgCtx.restore();

    // 只有桌機才補 pillarbox（左右黑邊）
    if (isDesktopDevice) {
      drawPillarBars(bgCtx, W, H);
    }
  } else {
    // 其他背景型別走原本流程（特效 / 月亮 / 影片等）
    renderBackground(W, H);
  }

  // 3) 清空頂層，準備人像覆蓋
  outCtx.clearRect(0, 0, W, H);

  // 4) 分割（只在影格變動時做）
  if (CONFIG.SEGMENTATION.ENABLED) {
    if (videoEl.currentTime !== lastVideoTime) {
      lastVideoTime = videoEl.currentTime;
      // 确保 MediaPipe 时间戳单调递增
      const timestamp = Math.max(now, lastTimestamp + 1);
      lastTimestamp = timestamp;
      const result = await mediaPipeManager.segmentImage(
        videoDrawCanvas,
        timestamp
      );
      if (result) {
        let maskF32 = null,
          mw = 0,
          mh = 0;
        if (result.confidenceMasks && result.confidenceMasks.length) {
          const idx =
            personLabelIndex < result.confidenceMasks.length
              ? personLabelIndex
              : 0;
          const cm = result.confidenceMasks[idx];
          if (cm?.getAsFloat32Array) {
            const src = cm.getAsFloat32Array();
            maskF32 = new Float32Array(src.length);
            maskF32.set(src);
            mw = cm.width;
            mh = cm.height;
          }
          for (const m of result.confidenceMasks) {
            try {
              m?.close?.();
            } catch {}
          }
        } else if (result.categoryMask?.getAsUint8Array) {
          const cat = result.categoryMask;
          const u8 = cat.getAsUint8Array();
          maskF32 = new Float32Array(u8.length);
          mw = cat.width;
          mh = cat.height;
          const personIdx = personLabelIndex;
          for (let i = 0; i < u8.length; i++)
            maskF32[i] = u8[i] === personIdx ? 1 : 0;
          try {
            cat.close?.();
          } catch {}
        }
        if (maskF32 && mw && mh) {
          const sm = emaUpdate(maskF32, mw, mh);
          gMaskCanvasProcessed = buildAlphaImage(sm, mw, mh);
        }
      }
    }
  } else {
    gMaskCanvasProcessed = null;
  }

  // 5) 先把人物合成到離屏（避免破壞底層）
  compositeCtx.clearRect(0, 0, W, H);
  compositeCtx.save();
  compositeCtx.drawImage(videoDrawCanvas, 0, 0, W, H);
  if (gMaskCanvasProcessed) {
    compositeCtx.globalCompositeOperation = "destination-in";
    compositeCtx.drawImage(gMaskCanvasProcessed, 0, 0, W, H);
    compositeCtx.globalCompositeOperation = "source-over";
  }
  compositeCtx.restore();

  // 6) 輸出：person_overlay 僅畫人像；其他模式畫整張 composite
  if (CONFIG.BACKGROUND?.TYPE === "person_overlay") {
    if (gMaskCanvasProcessed && CONFIG.SEGMENTATION.ENABLED) {
      // 不使用绘制镜像，让CSS镜像负责最终显示
      outCtx.drawImage(videoDrawCanvas, 0, 0, W, H);
      outCtx.globalCompositeOperation = "destination-in";
      outCtx.drawImage(gMaskCanvasProcessed, 0, 0, W, H);
      outCtx.globalCompositeOperation = "source-over";
    }
  } else {
    // 不使用绘制镜像，让CSS镜像负责最终显示
    outCtx.drawImage(compositeCanvas, 0, 0, W, H);
  }

  // 7) Mask 預覽
  maskCtx.clearRect(0, 0, W, H);
  if (gMaskCanvasProcessed && _showMaskPreview) {
    maskCtx.globalAlpha = 0.9;
    maskCtx.drawImage(gMaskCanvasProcessed, 0, 0, W, H);
    maskCtx.globalAlpha = 1.0;
    maskCanvas.style.display = "block";
  } else {
    maskCanvas.style.display = "none";
  }

  // 8) 臉部檢測（提示用）
  // 使用同一递增时间戳确保检测一致性
  const timestamp = Math.max(now, lastTimestamp + 1);
  lastTimestamp = timestamp;
  const det = mediaPipeManager.detectFaces(videoDrawCanvas, timestamp);
  if (det) renderOverlay(det.detections || []);
  else renderOverlay([]);

  requestAnimationFrame(renderLoop);
}

// -----------------------------------------------------------------------------
// 公開 API：start/stop/onResize & 參數 setters
// -----------------------------------------------------------------------------
export async function start() {
  if (running) return;
  const ok = initializeConfig();
  if (!ok) {
    onStatus("配置錯誤，請檢查控制台");
    return;
  }
  onStatus("初始化...");

  lastFaceDetectionState = false;

  // 初始化镜头模式和时间戳
  resetVideoTimestamp();
  // 這裡先同步一次（若 cameraManager 內部選了不同 facing，renderLoop 仍以 cameraManager 為準）
  setCurrentFacingMode(cameraManager.getCurrentFacingMode());

  syncCanvasSize();

  await mediaPipeManager.init(outCanvas);
  await cameraManager.startCamera(); // 讓 CameraManager 決定最穩的 constraints

  // 再同步一次實際被選到的 facing
  setCurrentFacingMode(cameraManager.getCurrentFacingMode());

  running = true;
  onStatus("檢測中");
  requestAnimationFrame(renderLoop);
}

export function stop() {
  running = false;
  cameraManager.stopCamera();
  if (outCtx && maskCtx && bgCtx) {
    outCtx.clearRect(0, 0, outCanvas.width, outCanvas.height);
    maskCtx.clearRect(0, 0, maskCanvas.width, maskCanvas.height);
    bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);
  }
  lastFaceDetectionState = false;

  onStats({ faceCount: 0, facesInArea: 0, moonActive: false });
  onStatus("已停止");
}

export function onResize() {
  if (running) syncCanvasSize();
}

